const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const raw = String(source.rawText || source.text || source.query || args.query || message.text || payload.text || '').trim();
const explicitQuery = String(source.query || args.query || '').trim();
const query = (explicitQuery || raw)
  .replace(/^(doc mail|đọc mail|doc email|đọc email|noi dung mail|nội dung mail|noi dung email|nội dung email|read mail|read email|open mail|open email)\s*/i, '')
  .replace(/\s+/g, ' ')
  .trim();
const messageId = String(source.messageId || args.messageId || '').trim();
const hasQuery = Boolean(query || messageId);
const guidance = '📧 <b>Đọc email</b>\n\nBạn hãy nhập theo mẫu:\n- đọc mail từ Google\n- nội dung mail về đơn hàng\n- read mail from boss';
return [{ json: { ...source, payload, message, chatId, query, messageId, hasQuery, response: hasQuery ? '' : guidance } }];

const source = $('Chuan Bi Doc Email').item.json || {};

const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
};

const formatDate = (value) => {
  if (value === undefined || value === null || value === '') return '';
  const normalized = /^\d+$/.test(String(value)) ? Number(value) : value;
  const date = new Date(normalized);
  return Number.isNaN(date.getTime())
    ? ''
    : date.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
};

const cleanText = (value = '') => String(value)
  .replace(/[\u034f\u061c\u115f\u1160\u17b4\u17b5\u180e\u200b-\u200f\u202a-\u202e\u2060-\u206f\ufeff]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const buildMailLink = (email) => {
  const threadId = pickFirst(email.threadId);
  const messageId = pickFirst(email.id);
  if (threadId) return `https://mail.google.com/mail/u/0/#inbox/${threadId}`;
  if (messageId) return `https://mail.google.com/mail/u/0/#inbox/${messageId}`;
  return '';
};

const rows = $input.all()
  .map((item) => item.json || {})
  .filter((email) => email && Object.keys(email).length > 0 && (email.id || email.subject || email.Subject || email.from || email.From || email.snippet));

if (!rows.length) {
  const query = pickFirst(source.query, source.messageId);
  return [{
    json: {
      ok: false,
      tool: 'gmail.read_email',
      chatId: source.chatId || '',
      text: query ? `Mia chưa tìm thấy email phù hợp với "${query}".` : 'Mia chưa tìm thấy email phù hợp.',
      links: [],
      result: {},
      meta: { query }
    }
  }];
}

const email = rows[0];
const from = cleanText(pickFirst(email.from?.value?.[0]?.name, email.from?.value?.[0]?.address, email.From, email.from, email.payload?.headers?.find((h) => h.name === 'From')?.value)) || 'Không rõ người gửi';
const to = cleanText(pickFirst(email.to?.value?.[0]?.address, email.To, email.to, email.payload?.headers?.find((h) => h.name === 'To')?.value));
const subject = cleanText(pickFirst(email.subject, email.Subject, email.payload?.headers?.find((h) => h.name === 'Subject')?.value)) || 'Không có tiêu đề';
const date = formatDate(pickFirst(email.date, email.Date, email.internalDate));
const link = buildMailLink(email);

let body = cleanText(pickFirst(email.textPlain, email.text, email.snippet)) || '(Email này không có nội dung văn bản để hiển thị.)';
let truncated = false;
if (body.length > 1400) {
  body = body.slice(0, 1400).trimEnd();
  truncated = true;
}

let text = `Mia đọc được email "${subject}"`;
text += `\nTừ: ${from}`;
if (to) text += `\nĐến: ${to}`;
if (date) text += `\nThời gian: ${date}`;
if (link) text += `\nLink: ${link}`;
text += `\n\nNội dung:\n${body}`;
if (truncated) text += '\n\nMia đã rút gọn phần cuối để Telegram dễ đọc hơn.';

return [{
  json: {
    ok: true,
    tool: 'gmail.read_email',
    chatId: source.chatId || '',
    text: text.trim(),
    links: link ? [link] : [],
    result: { email },
    meta: { subject, from, date }
  }
}];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
